components.css:
.ds-btn { position: relative; display: inline-flex; align-items: center; justify-content: center; gap: 8px; font-family: var(--font-body, Inter, system-ui, sans-serif); font-weight: 600; font-size: 0.95rem; text-decoration: none; padding: 14px 26px; border-radius: 100px; border: 1px solid transparent; cursor: pointer; isolation: isolate; overflow: hidden; transition: transform 0.35s var(--ease, cubic-bezier(0.16, 1, 0.3, 1)), border-color 0.3s var(--ease, cubic-bezier(0.16, 1, 0.3, 1)), color 0.3s var(--ease, cubic-bezier(0.16, 1, 0.3, 1)); }
.ds-btn-primary { background: var(--pink, #ff2c68); color: #fff; }
.ds-btn-primary::before { content: ""; position: absolute; inset: 0; z-index: -1; background: radial-gradient(circle at 50% 50%, var(--pink-deep, #e01259) 0%, var(--pink, #ff2c68) 60%); opacity: 1; transform: scale(1); transition: transform 0.45s var(--ease, cubic-bezier(0.16, 1, 0.3, 1)); }
.ds-btn-primary:hover::before { transform: scale(1.15); }
.ds-btn-primary:hover { transform: translateY(-1px); }
.ds-btn-primary:focus-visible { outline: none; box-shadow: 0 0 0 3px var(--pink-tint, #ffe4ee); }

.ds-btn-ghost { position: relative; display: inline-flex; align-items: center; justify-content: center; font-family: var(--font-body, Inter, system-ui, sans-serif); font-weight: 600; font-size: 0.95rem; text-decoration: none; padding: 14px 26px; border-radius: 100px; background: transparent; color: var(--ink, #14141a); border: 1px solid var(--paper-line, #ebe9ef); cursor: pointer; isolation: isolate; overflow: hidden; transition: color 0.3s var(--ease, cubic-bezier(0.16, 1, 0.3, 1)), border-color 0.3s var(--ease, cubic-bezier(0.16, 1, 0.3, 1)), transform 0.35s var(--ease, cubic-bezier(0.16, 1, 0.3, 1)); }
.ds-btn-ghost::before { content: ""; position: absolute; inset: 0; z-index: -1; background: var(--ink, #14141a); opacity: 0; transform: scale(0.4); transition: opacity 0.35s var(--ease, cubic-bezier(0.16, 1, 0.3, 1)), transform 0.45s var(--ease, cubic-bezier(0.16, 1, 0.3, 1)); }
.ds-btn-ghost:hover { color: #fff; border-color: var(--ink, #14141a); }
.ds-btn-ghost:hover::before { opacity: 1; transform: scale(1.15); }
.ds-btn-ghost:focus-visible { outline: none; box-shadow: 0 0 0 3px var(--pink-tint, #ffe4ee); }

.ds-field { display: block; font-family: var(--font-body, Inter, system-ui, sans-serif); }
.ds-field-label { display: block; font-size: 0.82rem; font-weight: 600; color: var(--ink, #14141a); margin-bottom: 6px; }
.ds-input { width: 100%; font: inherit; font-size: 0.95rem; padding: 11px 14px; border-radius: var(--radius-sm, 8px); border: 1px solid var(--paper-line, #ebe9ef); background: var(--paper, #ffffff); color: var(--ink, #14141a); }
.ds-input::placeholder { color: var(--ink-faint, #8b8b98); }
.ds-input:focus { outline: none; border-color: var(--pink, #ff2c68); box-shadow: 0 0 0 3px var(--pink-tint, #ffe4ee); }

.ds-card { background: var(--paper, #ffffff); border: 1px solid var(--paper-line, #ebe9ef); border-radius: var(--radius-lg, 22px); padding: 26px; box-shadow: 0 24px 48px -32px rgba(20, 20, 26, 0.25); font-family: var(--font-body, Inter, system-ui, sans-serif); }
.ds-card-label { font-size: 0.72rem; letter-spacing: 0.06em; text-transform: uppercase; color: var(--ink-faint, #8b8b98); margin-bottom: 20px; }
.ds-card-body { margin: 0; color: var(--ink-soft, #4a4a56); font-size: 1.02rem; line-height: 1.65; }

.ds-fork { position: relative; display: flex; flex-direction: column; gap: 12px; padding: 30px 26px; border: 1.5px solid var(--paper-line, #ebe9ef); border-radius: var(--radius-lg, 22px); background: var(--paper, #ffffff); text-decoration: none; color: var(--ink, #14141a); font-family: var(--font-body, Inter, system-ui, sans-serif); transition: transform 0.4s var(--ease, cubic-bezier(0.16, 1, 0.3, 1)), border-color 0.3s var(--ease, cubic-bezier(0.16, 1, 0.3, 1)), box-shadow 0.4s var(--ease, cubic-bezier(0.16, 1, 0.3, 1)); }
.ds-fork:hover { transform: translateY(-4px); border-color: var(--pink, #ff2c68); box-shadow: 0 20px 40px -22px rgba(255, 44, 104, 0.35); }
.ds-fork:focus-visible { outline: none; border-color: var(--pink, #ff2c68); box-shadow: 0 0 0 3px var(--pink-tint, #ffe4ee); }
.ds-fork-icon { width: 48px; height: 48px; display: inline-flex; align-items: center; justify-content: center; border-radius: 12px; background: var(--paper-alt, #faf9fb); color: var(--ink-soft, #4a4a56); transition: color 0.3s var(--ease, cubic-bezier(0.16, 1, 0.3, 1)), background 0.3s var(--ease, cubic-bezier(0.16, 1, 0.3, 1)); }
.ds-fork:hover .ds-fork-icon { background: var(--pink-tint, #ffe4ee); color: var(--pink-deep, #e01259); }
.ds-fork-title { font-family: var(--font-display, Space Grotesk, sans-serif); font-weight: 600; font-size: 1.3rem; letter-spacing: -0.01em; }
.ds-fork-sub { color: var(--ink-soft, #4a4a56); font-size: 0.95rem; line-height: 1.5; }

.ds-callout { padding: 20px 22px; background: var(--pink-tint-2, #fff0f5); border: 1px solid var(--pink-tint, #ffe4ee); border-left: 3px solid var(--pink, #ff2c68); border-radius: var(--radius-md, 14px); font-family: var(--font-body, Inter, system-ui, sans-serif); }
.ds-callout h3 { font-size: 1.05rem; margin: 0; }
.ds-callout p { margin-top: 8px; font-size: 0.96rem; color: var(--ink-soft, #4a4a56); }

.ds-placeholder { position: relative; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 10px; aspect-ratio: 4 / 3; min-height: 340px; border: 1.5px dashed var(--paper-line, #ebe9ef); border-radius: var(--radius-lg, 22px); background: repeating-linear-gradient(45deg, var(--paper-alt, #faf9fb) 0 10px, var(--paper, #ffffff) 10px 20px); font-family: var(--font-body, Inter, system-ui, sans-serif); text-align: center; padding: 24px; }
.ds-placeholder-tag { font-family: var(--font-mono, JetBrains Mono, Menlo, monospace); font-size: 0.66rem; letter-spacing: 0.06em; text-transform: uppercase; color: var(--ink-faint, #8b8b98); }
.ds-placeholder-label { font-size: 0.86rem; color: var(--ink-soft, #4a4a56); }
